-- ОКК: переформулировка критериев «Работа с возражениями» (ТОП3).
-- Прежние ai_prompt заставляли агента искать «аргументацию тех/сроки/цена» — это не тот смысл.
-- Правило: менеджер задаёт клиенту вопрос о конкурентности (тех/сроки/цена), получает ответ,
-- при отрицательном ответе отрабатывает возражение, и заносит результат в поле CRM «ТОП3…».
-- Оценка (один вердикт на параметр):
--   • гейт по статусу решается в коде (lib/okk-evaluator.ts) — критерий применяется только начиная
--     со статуса «Согласование параметров заказа» (na-soglasovanii) и на всех последующих;
--   • значения полей ТОП3 из raw_payload.customFields прокидываются в контекст оценщика для сверки.
-- Аддитивно: только UPDATE существующих строк реестра, схема не меняется.

UPDATE public.okk_criteria SET
    ai_prompt = 'Работа с возражением по ТЕХ. ХАРАКТЕРИСТИКАМ. Ниже дано значение поля CRM «ТОП3 Проходим по тех. характеристикам». Верни TRUE, только если ВСЁ верно: (1) менеджер в звонке выяснил у клиента, устраивают ли его наши тех. характеристики или у конкурента лучше, и получил ответ; (2) если клиент назвал конкурента лучше — менеджер попытался снять возражение; (3) поле CRM заполнено и НЕ противоречит ответу клиента. Верни FALSE, если: тему тех. характеристик в звонке не подняли (reason: «параметр не выяснен у клиента»); ИЛИ вопрос задан и ответ получен, но поле CRM пустое (reason дословно: «вопрос задан и ответ получен, но в CRM не внесено»); ИЛИ значение поля противоречит ответу клиента (reason: «поле CRM противоречит ответу клиента»); ИЛИ возражение всплыло и не отработано. Это НЕ про то, хвалил ли менеджер товар, — это про то, выявил ли он позицию клиента, отработал возражение и корректно занёс результат в CRM.',
    how_tip = 'GPT: задан ли вопрос о тех. конкурентности, отработано ли возражение, соответствует ли поле CRM ответу клиента',
    data_tip = 'raw_telphin_calls.transcript + orders.raw_payload.customFields.top3_prokhodim_po_tekh_kharakteristikam → GPT'
WHERE key = 'script_offer_best_tech';

UPDATE public.okk_criteria SET
    ai_prompt = 'Работа с возражением по СРОКАМ ПОСТАВКИ. Ниже дано значение поля CRM «ТОП3 Проходим по срокам». Верни TRUE, только если ВСЁ верно: (1) менеджер в звонке выяснил у клиента, устраивают ли его наши сроки или у конкурента лучше, и получил ответ; (2) если клиент назвал конкурента лучше — менеджер попытался снять возражение; (3) поле CRM заполнено и НЕ противоречит ответу клиента. Верни FALSE, если: тему сроков в звонке не подняли (reason: «параметр не выяснен у клиента»); ИЛИ вопрос задан и ответ получен, но поле CRM пустое (reason дословно: «вопрос задан и ответ получен, но в CRM не внесено»); ИЛИ значение поля противоречит ответу клиента (reason: «поле CRM противоречит ответу клиента»); ИЛИ возражение всплыло и не отработано. Это НЕ про то, хвалил ли менеджер сроки, — это про то, выявил ли он позицию клиента, отработал возражение и корректно занёс результат в CRM.',
    how_tip = 'GPT: задан ли вопрос о конкурентности по срокам, отработано ли возражение, соответствует ли поле CRM ответу клиента',
    data_tip = 'raw_telphin_calls.transcript + orders.raw_payload.customFields.top3_prokhodim_po_srokam1 → GPT'
WHERE key = 'script_offer_best_terms';

UPDATE public.okk_criteria SET
    ai_prompt = 'Работа с возражением по ЦЕНЕ. Ниже дано значение поля CRM «ТОП3 Проходим ли по цене». Верни TRUE, только если ВСЁ верно: (1) менеджер в звонке выяснил у клиента, устраивает ли его наша цена или у конкурента лучше, и получил ответ; (2) если клиент назвал конкурента дешевле — менеджер попытался снять возражение; (3) поле CRM заполнено и НЕ противоречит ответу клиента. Верни FALSE, если: тему цены в звонке не подняли (reason: «параметр не выяснен у клиента»); ИЛИ вопрос задан и ответ получен, но поле CRM пустое (reason дословно: «вопрос задан и ответ получен, но в CRM не внесено»); ИЛИ значение поля противоречит ответу клиента (reason: «поле CRM противоречит ответу клиента»); ИЛИ возражение всплыло и не отработано. Это НЕ про то, обосновывал ли менеджер цену, — это про то, выявил ли он позицию клиента, отработал возражение и корректно занёс результат в CRM.',
    how_tip = 'GPT: задан ли вопрос о конкурентности по цене, отработано ли возражение, соответствует ли поле CRM ответу клиента',
    data_tip = 'raw_telphin_calls.transcript + orders.raw_payload.customFields.top3_prokhodim_li_po_tsene2 → GPT'
WHERE key = 'script_offer_best_price';
